import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

import { tsc } from "@tsrs/wasm";
import { afterAll, beforeAll, describe, expect, it } from "vite-plus/test";

import { compilerOptions } from "./type-check.ts";

// The `@server/_generated/api` module the host generates for an App,
// type-checked as the App compiler checks App code (its options, with
// tsrs, the platform's checker): a page importing it, and a seal,
// type-check it with the App's own files. The SDK's Notes fixture is
// generated byte for byte as the host makes it
// (packages/sdk/test/references.test.ts), and it binds workflows with
// events, decisions and queries, so every part of a reference is in it.

const references = path.resolve(
  import.meta.dirname,
  "../../sdk/test/notes/server/_generated/api.ts"
);

let scratch = "";

/** The errors tsrs reports in `file`, as `TS<code>: <message>`. */
const errorsIn = async (file: string): Promise<string[]> => {
  const { paths: _paths, ...options } = compilerOptions;
  const config = path.join(scratch, "tsconfig.json");
  writeFileSync(
    config,
    JSON.stringify({
      // Its declarations aren't App code: only the module's own errors count.
      compilerOptions: { ...options, skipLibCheck: true },
      files: [file],
    })
  );
  const { diagnostics = [] } = await tsc(["-p", config], {
    diagnostics: "json",
  });
  return diagnostics
    .filter(
      // The program's own errors too: a file it couldn't read is one.
      (diagnostic) =>
        diagnostic.category === 1 &&
        (diagnostic.fileName === undefined || diagnostic.fileName === file)
    )
    .map((diagnostic) => `TS${diagnostic.code}: ${diagnostic.text}`);
};

// A whole program type-checked from cold: past the default 5 s on a
// busy runner, so the time other type-check tests have
// (apps/core/test/workflow-type-check.test.ts).
describe("the generated references", { timeout: 120_000 }, () => {
  beforeAll(() => {
    scratch = mkdtempSync(path.join(tmpdir(), "grasp-references-"));
  });

  afterAll(() => {
    rmSync(scratch, { recursive: true, force: true });
  });

  it("type-check as the App compiler checks them, workflows and all", async () => {
    await expect(errorsIn(references)).resolves.toStrictEqual([]);
  });
});
